#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define PB push_back
#define sz(s) int((s).size())
#define bit(n,k) (((n)>>(k))&1)

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef unsigned int ui;

const int Lg=18, Tw=(1<<Lg), Max=Tw+10;

int Ans[Max][Lg+3], tmp[Lg+3], tmp2[Lg+3], fac[Max], ifac[Max], N, n, mod=1e9+7;

int power(int a, int b){
    int res=1;
    while(b){
        if(b&1) res=1ll*res*a%mod;
        a=1ll*a*a%mod;
        b>>=1;
    }
    return res;
}

void add_arrays(int *a,int *b){
    for(int i=0;i<=N;i++)
        a[i]=(a[i]+b[i])%mod;
}

void subtract_arrays(int *a,int *b){
    for(int i=0;i<=N;i++)
        a[i]=(a[i]-b[i])%mod;
}

void multiply_arrays(int *ans,int *a,int *b){
    memset(tmp,0,sizeof tmp);
    for(int i=0;i<=N;i++){
        for(int j=0;j<=i;j++){
            tmp[i]=(tmp[i]+1ll*a[j]*b[i-j])%mod;
        }
    }
    memcpy(ans,tmp,sizeof tmp);
}

void transform_forward(int a[][Lg+3]){
    for(int i=0;i<N;i++)
        for(int msk=n;msk>=0;msk--)
            if(bit(msk,i))
                add_arrays(a[msk],a[msk ^ (1<<i)]);
}

void transform_inverse(int a[][Lg+3]){
    for(int i=0;i<N;i++)
        for(int msk=n;msk>=0;msk--)
            if(bit(msk,i))
                subtract_arrays(a[msk],a[msk ^ (1<<i)]);
}

vector<int> bits;

int main(){
    int K; cin>>n>>K>>mod;
    int answer=power(K,n);
    if(n&1) { cout<<answer<<endl; return 0; }
    N=__builtin_popcount(n);
    int N_before=n;
    for(int i=0;i<Lg;i++){
        if(bit(n,i))
            bits.PB(i);
    }
    n=(1<<N)-1;
    fac[0]=1;
    for(int i=1;i<Max;i++)
        fac[i]=1ll*i*fac[i-1]%mod;
    ifac[Max-1]=power(fac[Max-1],mod-2);
    for(int i=Max-2;i>=0;i--)
        ifac[i]=1ll*(i+1)*ifac[i+1]%mod;
    for(int i=0;i<=n;i++){
        int Real=0;
        for(int j=0;j<N;j++)
            Real+=bit(i,j)*(1<<bits[j]);
        Ans[i][__builtin_popcount(i)]=ifac[Real];
    }
    transform_forward(Ans);
    for(int i=0;i<=n;i++){
        int KK=K;
        memset(tmp2,0,sizeof tmp2); tmp2[0]=1;
        while(KK){
            if(KK&1) multiply_arrays(tmp2,tmp2,Ans[i]);
            multiply_arrays(Ans[i],Ans[i],Ans[i]);
            KK>>=1;
        }
        memcpy(Ans[i],tmp2,sizeof tmp2);
    }
    transform_inverse(Ans);
    answer=(answer - 1ll*Ans[n][N]*fac[N_before])%mod;
    if(answer<0) answer+=mod;
    cout<<answer<<endl;
    return 0;
}
